int multiply_poly(int n1,int n2)
{
    int i,j;
    for(i=0;i<30;i++)
        prod[i]=0;
    for(i=0;i<=n1;i++)
    {
        for(j=0;j<=n2;j++)
        {
            prod[i+j]=prod[i+j]+poly_n1[i]*poly_n2[j];
        }
    }
    return 0;
}

int print_poly(int n)
{
    int i;
    for(i=n;i>=0;i--)
        printf("%d ",prod[i]);
        return 0;
}

